<?php
namespace App\Livewire;
use App\Models\SchoolClass;use App\Models\Student;use App\Models\Term;use App\Services\TermReportCalculator;use Illuminate\Support\Facades\Auth;use Livewire\Attributes\Layout;use Livewire\Component;
#[Layout('layouts.app')] class BulkTermReports extends Component {public string $termId='',$classId='';public function mount():void{$s=Auth::user()->school;$this->termId=(string)$s->currentTerm()?->id;$this->classId=(string)SchoolClass::where('school_id',$s->id)->value('id');}public function render(){$school=Auth::user()->school;$term=Term::where('school_id',$school->id)->find($this->termId);$students=$term&&$this->classId?Student::with(['schoolClass','guardians'])->where(['school_id'=>$school->id,'school_class_id'=>$this->classId,'status'=>'active'])->orderBy('name')->get():collect();$reports=$term?$students->map(fn($student)=>['student'=>$student,'data'=>TermReportCalculator::student($student,$term)]):collect();return view('livewire.bulk-term-reports',['terms'=>Term::where('school_id',$school->id)->latest('year')->get(),'classes'=>SchoolClass::where('school_id',$school->id)->get(),'term'=>$term,'reports'=>$reports,'pageTitle'=>'Bulk Term Reports']);}}
